#include <stdio.h>
#include <algorithm>

using namespace std;

#define N 102

int main()
{
    int n, d, m;

    scanf("%d%d", &n, &d);
    int price[N] = {0};

    for (int i = 1; i <= n; i++)
    {
        scanf("%d", &price[i]);
    }

    sort(price, price + n + 1);

    for (int i = 1; i <= n; i++)
    {
        price[i] += price[i - 1];
    }

    scanf("%d", &m);
    int benefit = (m > n) ? price[n] - (m - n) * d : price[m];
    printf("%d\n", benefit);

    return 0;
}

